-- =============================================================
-- Recarga de asignaciones remito-factura desde GVA54 de Tango
-- Corrige los remitos históricos que entregaron para más de una factura.
-- Sin BEGIN/COMMIT: usar ensayo_recarga_gva54.sql o aplicar_recarga_gva54.sql
-- =============================================================

\echo '── Desactivando trigger de auditoría para carga masiva...'
ALTER TABLE remito_item_facturas DISABLE TRIGGER trg_audit;

\echo '── Eliminando asignaciones viejas de Tango...'
DELETE FROM remito_item_facturas WHERE origen = 'tango';

\echo '── Insertando 14.850 asignaciones exactas de GVA54...'

\echo '── Reactivando trigger de auditoría...'
ALTER TABLE remito_item_facturas ENABLE TRIGGER trg_audit;

\echo '── Ajustando secuencia...'
SELECT setval('remito_item_facturas_id_seq', COALESCE((SELECT MAX(id) FROM remito_item_facturas), 1), (SELECT COUNT(*) > 0 FROM remito_item_facturas));

\echo '── Recalculando estado y factura_id de remitos...'
UPDATE remitos r SET
  factura_id = (
    SELECT a.factura_id
    FROM remito_item_facturas a
    JOIN remito_items ri ON ri.id = a.remito_item_id
    WHERE ri.remito_id = r.id
    ORDER BY a.id
    LIMIT 1),
  estado = CASE WHEN NOT EXISTS (
      SELECT 1 FROM remito_items ri
      WHERE ri.remito_id = r.id
        AND ri.cantidad > COALESCE((
          SELECT sum(a.cantidad)
          FROM remito_item_facturas a JOIN facturas fa ON fa.id = a.factura_id
          WHERE a.remito_item_id = ri.id AND fa.estado <> 'anulada'
            AND fa.estado_fiscal IN ('historico','autorizado')), 0))
    THEN 'facturado' ELSE 'pendiente' END,
  updated_at = NOW()
WHERE r.estado <> 'anulado';

\echo '── Recalculando remito_id de facturas...'
UPDATE facturas f SET remito_id = x.remito_id
FROM (
  SELECT f_inner.id as fac_id, (
    SELECT r.id
    FROM remito_item_facturas a
    JOIN remito_items ri ON ri.id = a.remito_item_id
    JOIN remitos r ON r.id = ri.remito_id
    WHERE a.factura_id = f_inner.id
    ORDER BY r.numero, r.id
    LIMIT 1) AS remito_id
  FROM facturas f_inner
) x
WHERE f.id = x.fac_id AND f.remito_id IS DISTINCT FROM x.remito_id;

\echo '── Verificaciones Almajo y conteos globales...'
DO $$
DECLARE
  v_pend_2013 numeric;
  v_pend_2043 numeric;
  v_pend_2114 numeric;
  v_pend_2230 numeric;
  v_pend_2296 numeric;
  v_tot_facs  int;
  v_facs_2026 int;
BEGIN
  -- Facturas viejas de Almajo deben dar 0
  SELECT COALESCE(sum(pendiente), 0) INTO v_pend_2013 FROM crm_facturas_pendientes(482) WHERE factura_id = 8129;
  SELECT COALESCE(sum(pendiente), 0) INTO v_pend_2043 FROM crm_facturas_pendientes(482) WHERE factura_id = 8189;
  SELECT COALESCE(sum(pendiente), 0) INTO v_pend_2114 FROM crm_facturas_pendientes(482) WHERE factura_id = 8330;
  
  IF v_pend_2013 <> 0 OR v_pend_2043 <> 0 OR v_pend_2114 <> 0 THEN
    RAISE EXCEPTION 'FALLA: Almajo sigue teniendo saldo pendiente en facturas viejas (2013: %, 2043: %, 2114: %)',
      v_pend_2013, v_pend_2043, v_pend_2114;
  END IF;

  -- Facturas 2230 y 2296
  SELECT COALESCE(sum(pendiente), 0) INTO v_pend_2230 FROM crm_facturas_pendientes(482) WHERE factura_id = 8564;
  SELECT COALESCE(sum(pendiente), 0) INTO v_pend_2296 FROM crm_facturas_pendientes(482) WHERE factura_id = 8699;

  IF v_pend_2230 <> (4830 + 46) OR v_pend_2296 <> (25200 + 240) THEN
    RAISE EXCEPTION 'FALLA: Almajo 2230 o 2296 no coinciden con lo esperado (2230: %, 2296: %)',
      v_pend_2230, v_pend_2296;
  END IF;

  SELECT count(DISTINCT p.factura_id),
         count(DISTINCT p.factura_id) FILTER (WHERE f.fecha >= '2026-01-01' AND f.fecha < '2027-01-01')
    INTO v_tot_facs, v_facs_2026
  FROM crm_facturas_pendientes(NULL) p
  JOIN facturas f ON f.id = p.factura_id;

  RAISE NOTICE 'OK: Almajo 2013, 2043 y 2114 canceladas (0 pendiente).';
  RAISE NOTICE 'OK: Almajo 2230 (46 pal) y 2296 (240 pal) intactas.';
  RAISE NOTICE 'INFO: Total facturas pendientes en el sistema: % (de 2026: %)', v_tot_facs, v_facs_2026;
END $$;
